@Component("aTM-handler")
@ProcessingGroup("aTM-processing-group")
public class ATMEventHandler {
	
	// core constructor
	ATMEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateATMEvent
     */
    @EventHandler
    public void handle( CreateATMEvent event) {
        entityManager.persist(new ATM(event.getATMId(), event.getTerminalId(), event.getLocation(), event.getBranch(), event.getStatus()));
    }

    /*
     * @param	event UpdateATMEvent
     */
    @EventHandler
    public ATM handle( UpdateATMEvent event) {
    	entityManager.merge(new ATM(event.getATMId(), event.getTerminalId(), event.getLocation(), event.getBranch(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteATMEvent
     */
    @EventHandler
    public void on( DeleteATMEvent event) {
    	ATM entity = new ATM();
   
    	// ------------------------------------------
    	// apply the ATMId
    	// ------------------------------------------
    	entity.setATMId( event.getATMId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ATMRepository aTMEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ATMEventHandler.class.getName());

}
